from decimal import Decimal
from typing import Any, Callable


Guard = Callable[[dict, dict], bool]


def _legacy_value(value: Any) -> Any:
    """Represent a missing/null legacy scalar as its empty-string value."""
    return "" if value is None else value


def _numeric(value: Any) -> Decimal:
    """Apply the numeric coercion needed by this workflow's VRL guard."""
    value = _legacy_value(value)
    if value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value).strip() or "0")


def _positive_total(record: dict, tables: dict) -> bool:
    # NVL(TOT_AMT, 0) > 0
    del tables
    return _numeric(record.get("TOT_AMT", "")) > Decimal(0)


def _lookup_account_credit_hold(record: dict, tables: dict) -> Any:
    """Perform the workflow's ordered, soft-delete-aware legacy LOOKUP."""
    account_id = _legacy_value(record.get("ACCT_ID", ""))

    for row in tables.get("ACCT_MASTER", []):
        if _legacy_value(row.get("DEL_FLG", "")) == "Y":
            continue
        if _legacy_value(row.get("ACCT_ID", "")) == account_id:
            return _legacy_value(row.get("CRED_HOLD", ""))

    return ""


def _account_not_on_credit_hold(record: dict, tables: dict) -> bool:
    # LOOKUP(ACCT_MASTER, ACCT_ID, ACCT_ID, CRED_HOLD) <> 'Y'
    return _lookup_account_credit_hold(record, tables) != "Y"


