_TRANSITIONS: tuple[
    tuple[str, str, str, Guard | None, tuple[str, ...], tuple[str, ...]], ...
] = (
    ("E", "approve", "A", _positive_total, ("ORD_APPR",), ()),
    ("A", "ship", "S", None, ("ORD_SHIP",), ("shipped",)),
    ("S", "invoice", "I", None, ("ORD_INV",), ()),
    ("E", "cancel", "X", None, ("ORD_CANC",), ()),
    (
        "A",
        "cancel",
        "X",
        _account_not_on_credit_hold,
        ("ORD_CANC",),
        (),
    ),
    (
        "I",
        "cancel",
        "X",
        None,
        ("ORD_CANC_INV",),
        ("credit_note",),
    ),
)


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire the first matching order_fulfilment transition."""
    record_copy = dict(record)

    for (
        from_state,
        transition_event,
        to_state,
        guard,
        audits,
        notifies,
    ) in _TRANSITIONS:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(record, tables):
            continue

        return {
            "state": to_state,
            "record": record_copy,
            "audits": list(audits),
            "notifies": list(notifies),
            "matched": True,
        }

    return {
        "state": state,
        "record": record_copy,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
